"""Original Java exercises: JVM, contracts, resources, streams, concurrency."""
from build import S, lesson as L


def lessons():
 result = [
 L('toolchain','JDK, bytecode, and entry points','javac compiles source into JVM bytecode; java launches a class or a source file. A conventional entry point is public static void main(String[] args). JShell evaluates snippets interactively. A package name is part of a class name, not merely a folder label.',
 S('$ ~javac~ Main.java','Compiles Main.java to bytecode','Runs only the tests|Starts JShell','javac is the JDK compiler; the resulting class is launched separately.','java|jshell','What does this terminal command do?'),
 S('$ java Main ~${word}~','Passes ${word} as args[0]','Passes Main as args[0]|Creates a package','Arguments following the main class name become application arguments.','--version|--help','What is passed to main?'),
 S('public ~static~ void main(String[] args) {}','No instance is required to invoke this entry point','Creates an instance automatically|Makes args immutable','static attaches the method to the class rather than an object.','final|abstract','What does the highlighted modifier mean?'),
 S('$ ~jshell~','Starts an interactive Java REPL','Compiles every project file|Runs Maven','JShell is useful for checking isolated declarations and expressions.','javac|jar','What tool is started?')),
 L('values','Primitive values and local inference','Java distinguishes primitive values from object references. var infers a local type; it does not make the binding dynamically typed. final prevents reassignment, not mutation through a reference. Integer division truncates; explicit conversion changes numeric behavior.',
 S('int count=${n}; count~++~; System.out.println(count);','${next}','${n}|${prev}','Post-increment changes count before the subsequent print.','--|+= 0'),
 S('var text="${word}"; System.out.println(text.~length()~);','${length}','${n}|0','var infers String, whose length method returns the number of UTF-16 code units. These words are ASCII.','isEmpty()|hashCode()'),
 S('System.out.println(${n} ~/ ~${m});','${div}','${mul}|${add}','Both operands are integers, so division discards the fractional part.','*|+'),
 S('final int count=${n}; ~count++;~','Compile error: final binding reassigned','${next}|No error','A final primitive binding cannot be assigned a new value.','System.out.println(count);|System.out.println(0);','Does this compile?')),
 L('text','Strings, equality, and builders','String is immutable. equals compares content; == compares references. Avoid relying on string interning when reading equality. StringBuilder accumulates mutable text. Conversion methods can fail on malformed input.',
 S('String a=new String("${word}"); System.out.println(a.~equals~("${word}"));','true','false|null','equals compares characters even when the strings are separate objects.','compareTo|indexOf'),
 S('String s="${word}"; s.toUpperCase(); System.out.println(~s~);','${word}','${upper}|Compile error','Ignoring the returned String leaves the original binding unchanged.','s.toUpperCase()|s.length()'),
 S('var s=new StringBuilder("${word}"); s.~append~("!"); System.out.println(s);','${word}!','${word}|!','append changes the builder and returns it for chaining.','indexOf|lastIndexOf'),
 S('System.out.println(Integer.~parseInt~("${n}")+1);','${next}','${n}1|Compile error','parseInt converts decimal text into an int before addition.','valueOf("0").compareTo|toString')),
 L('branches','Boolean conditions and switch expressions','Conditions require booleans. && and || short-circuit; & on booleans evaluates both operands. Modern switch expressions yield values and arrow arms avoid fall-through. Exhaustiveness matters for expression results.',
 S('int n=${n}; System.out.println(n ~>~ 0 ? "yes" : "no");','yes','no|Compile error','The positive input selects the first conditional expression value.','<|=='),
 S('int n=0; boolean ok=false ~&&~ (++n>0); System.out.println(n);','0','1|Compile error','The right operand is not evaluated when the left side is false.','&|||'),
 S('int n=switch("ready"){case "ready" ~->~ ${n}; default -> 0;}; System.out.println(n);','${n}','0|Compile error','Arrow arms yield an expression result without ordinary switch fall-through.',':|=>'),
 S('int n=switch(1){default -> {~yield~ ${n};}}; System.out.println(n);','${n}','1|Compile error','yield supplies the value of a block arm in a switch expression.','return|break')),
 L('loops','Iteration, arrays, and boundaries','Arrays have fixed length and zero-based indexing. Enhanced for visits values; assigning to a primitive loop variable does not update the array. break exits a loop and continue skips the rest of one iteration.',
 S('int[] a={${n},${m}}; System.out.println(a.~length~);','2','1|Compile error','Array length is a field, unlike String.length().','length()|size()'),
 S('int[] a={${n}}; for(int v:a){v++;} System.out.println(~a[0]~);','${n}','${next}|0','v is a copy of the primitive element, not a mutable alias to it.','a.length|a[1]'),
 S('int n=0; for(int i=0;i<${n};i++){n++;} System.out.println(~n~);','${n}','${next}|0','The loop runs for i from zero through ${prev}.','0|n+1'),
 S('int n=0; for(int i=0;i<3;i++){if(i==1) ~continue~; n++;} System.out.println(n);','2','1|3','Only the middle iteration skips its increment.','break|return')),
 L('methods','Methods, overloads, and pass-by-value','Method parameter types and arity determine overload selection. Java always passes values: an object reference is itself a copied value. Mutating a referenced object is visible, but reassigning a parameter does not rebind the caller variable.',
 S('class Util {static int bump(int x){return ~x+1~;}}\nSystem.out.println(Util.bump(${n}));','${next}','${n}|0','The static helper returns the computed integer.','x|0'),
 S('class Util {static void reset(int x){x=0;}}\nint n=${n}; Util.reset(n); System.out.println(~n~);','${n}','0|Compile error','Changing the copied primitive parameter leaves the caller variable intact.','n+1|0'),
 S('class Util {static void change(int[] a){a[0]=${m};}}\nint[] a={${n}}; Util.change(a); System.out.println(a[~0~]);','${m}','${n}|Compile error','The copied reference still refers to the caller array.','1|2'),
 S('class Util {static String kind(int n){return "int";} static String kind(String s){return "text";}}\nSystem.out.println(Util.kind(~"${word}"~));','text','int|Compile error','The String argument selects the String overload at compile time.','${n}|0')),
 L('classes','Constructors and encapsulation','Constructors establish object state; private fields hide representation. this distinguishes a receiver field from a parameter with the same name. Instance methods operate on an object; static fields belong to the class.',
 S('class Counter {private int n; Counter(int n){~this.n~ = n;} int value(){return n;}}\nSystem.out.println(new Counter(${n}).value());','${n}','0|Compile error','this.n names the field, while n alone names the parameter.','n|this'),
 S('class Counter {int n; void bump(){n++;}}\nvar c=new Counter(); c.~bump()~; System.out.println(c.n);','1','0|Compile error','An instance method mutates this object.','toString()|hashCode()'),
 S('class Box {static int count=${n};}\nSystem.out.println(~Box.count~);','${n}','0|Compile error','A static field can be read using the class name.','Box|Box.count()'),
 S('class Box {~private~ int n=${n}; int value(){return n;}}','The field is hidden behind an accessor','The field is immutable|The field belongs to the class','private restricts access; it does not imply final or static.','public|static','What contract does the field modifier express?')),
 L('interfaces','Interfaces and dynamic dispatch','An interface expresses required behavior. A class implements it explicitly; overriding chooses runtime instance behavior. Prefer composition when code only needs a capability. An interface default method can supply reusable behavior.',
 S('interface Label {String text();}\nclass Item ~implements~ Label {public String text(){return "${word}";}}\nLabel x=new Item(); System.out.println(x.text());','${word}','Compile error|null','implements declares conformance and the public method fulfills the interface contract.','extends|instanceof'),
 S('class Base {String text(){return "base";}}\nclass Child extends Base {String text(){return "${word}";}}\nBase x=~new Child()~; System.out.println(x.text());','${word}','base|Compile error','The overridden instance method is selected from the runtime object type.','new Base()|null'),
 S('interface Named {~default~ String name(){return "${word}";}}\nclass Item implements Named {}\nSystem.out.println(new Item().name());','${word}','null|Compile error','A default method supplies inherited interface behavior.','abstract|private'),
 S('interface Sized {int size();}\nSized item=~() -> ${n}~; System.out.println(item.size());','${n}','0|Compile error','An interface with one abstract method can be implemented by a compatible lambda.','${n}|null')),
 L('collections','Collection APIs and mutability','List, Set, and Map are API contracts, not implementation algorithms. List.of creates an unmodifiable list. ArrayList supports mutation. Generic collections store reference types, so integers use boxing. Missing map values require deliberate handling.',
 S('var a=new java.util.ArrayList<Integer>(); a.~add~(${n}); System.out.println(a.get(0));','${n}','0|Compile error','add appends an element; get reads by index.','remove|contains'),
 S('var a=java.util.List.of(${n},${m}); System.out.println(a.~size()~);','2','1|Compile error','size returns the number of list elements.','length|length()'),
 S('var m=new java.util.HashMap<String,Integer>(); System.out.println(m.~getOrDefault~("${word}",${n}));','${n}','null|0','getOrDefault supplies a fallback for an absent mapping.','put|remove'),
 S('var s=new java.util.HashSet<String>(); s.add("${word}"); s.add("${word}"); System.out.println(s.~size()~);','1','2|0','A set retains only one equal element.','hashCode()|isEmpty()')),
 L('generics','Type parameters and variance','Generics preserve element types across APIs. List<Integer> is not a subtype of List<Number>. ? extends T allows reading T values; ? super T permits inserting T values. Type erasure means ordinary generic type arguments are not reified at runtime.',
 S('java.util.List<~String~> names=java.util.List.of("${word}"); System.out.println(names.get(0).length());','${length}','Compile error|0','The generic parameter preserves String operations on retrieved elements.','Integer|Object'),
 S('java.util.List<? ~extends~ Number> a=java.util.List.of(${n}); System.out.println(a.get(0).intValue());','${n}','0|Compile error','An upper bound allows reading each element as Number.','super|implements'),
 S('java.util.List<? ~super~ Integer> a=new java.util.ArrayList<Number>(); a.add(${n}); System.out.println(a.size());','1','0|Compile error','A lower bound permits storing Integer values in a collection of some supertype.','extends|implements'),
 S('class Util {static <T> ~T~ first(java.util.List<T> xs){return xs.get(0);}}\nSystem.out.println(Util.first(java.util.List.of("${word}")));','${word}','Compile error|null','The same type parameter connects the argument element type with the return type.','int|void')),
 L('errors','Exceptions and recovery boundaries','Checked exceptions must be caught or declared. Runtime exceptions are unchecked but still need a sensible boundary. Catch a specific type when recovery depends on it. finally runs on normal returns and exceptional exits; returning from finally can hide failures.',
 S('try {Integer.parseInt("bad");} catch(~NumberFormatException~ e){System.out.println("invalid");}','invalid','bad|Compile error','Malformed integer text throws NumberFormatException.','java.io.IOException|InterruptedException'),
 S('try {System.out.println("${word}");} ~finally~ {System.out.println("done");}','${word}\ndone','done|${word}','finally executes after the try body, even when no exception occurs.','else|catch'),
 S('class Util {static void fail() ~throws~ java.io.IOException {throw new java.io.IOException();}}','Callers must handle or declare IOException','All exceptions are suppressed|The method returns an exception value','throws advertises a checked exception; throw actually raises it.','throw|catch','What obligation does the declaration introduce?'),
 S('try {throw new IllegalArgumentException("${word}");} catch(IllegalArgumentException e){System.out.println(e.~getMessage()~);}','${word}','null|Compile error','getMessage retrieves the diagnostic supplied at construction.','getCause()|getClass()')),
 L('resources','Files and deterministic cleanup','Garbage collection reclaims memory, not timely file closure. try-with-resources closes AutoCloseable resources on every exit. Files and Path provide modern file APIs; streams returned from Files.lines also need closing. Explicit text encodings make file contracts clearer.',
 S('~try~ (var r=new java.io.StringReader("${word}")){System.out.println((char)r.read());}','${first}','${word}|Compile error','A resource declared in try parentheses is closed when the block ends.','if|while'),
 S('var p=java.nio.file.Path.~of~("folder","${word}.txt"); System.out.println(p.getFileName());','${word}.txt','folder|Compile error','Path.of constructs a path without opening or creating a file.','get|parse'),
 S('// Assume notes.txt is writable.\njava.nio.file.Files.~writeString~(java.nio.file.Path.of("notes.txt"),"${word}");','Writes UTF-8 text, creating or truncating the file','Appends by default|Only creates a path','The default writeString operation writes text and closes its internally opened file.','readString|delete','What happens to the file?'),
 S('class Resource implements AutoCloseable {public void close(){System.out.println("closed");}}\ntry(var r=~new Resource()~){System.out.println("${word}");}','${word}\nclosed','${word}|closed','The resource close method runs after the body.','null|new Object()')),
 L('records','Records and sealed domain models','Records declare data carriers with component accessors and value-based equality; their immutability is shallow. Sealed types constrain permitted subtypes. Pattern matching can inspect a value while introducing a typed binding.',
 S('record Item(String name,int count) {}\nvar item=new Item("${word}",${n}); System.out.println(item.~name()~);','${word}','${n}|Compile error','A record component generates an accessor named after that component.','getName()|name'),
 S('record Item(int count) {}\nSystem.out.println(new Item(${n}).~equals~(new Item(${n})));','true','false|Compile error','Record equality compares components of records of the same type.','getClass().equals|toString().equals'),
 S('Object value="${word}"; if(value ~instanceof String text~){System.out.println(text.length());}','${length}','0|Compile error','The type pattern checks the runtime type and binds a String within this branch.','== String text|instanceof Integer text'),
 S('// Top-level declarations in one source file:\nsealed interface State ~permits~ Ready {}\nfinal class Ready implements State {}','Only declared permitted direct subtypes can implement State','Any class may directly implement State|Ready is a record','permits restricts the direct subtype set; permitted types must specify their own extension policy.','extends|implements','What does the sealed declaration ensure?')),
 L('lambdas','Lambdas and captured variables','Functional interfaces give lambdas a target type. Method references name an existing compatible method. Captured local variables must be final or effectively final; mutation of an object referenced by such a variable is a separate matter.',
 S('java.util.function.IntUnaryOperator f=x ~->~ x+1; System.out.println(f.applyAsInt(${n}));','${next}','${n}|Compile error','The lambda maps an int to an int.','=>|:'),
 S('java.util.function.Function<String,Integer> f=String~::~length; System.out.println(f.apply("${word}"));','${length}','0|Compile error','An unbound method reference takes its receiver from the function argument.','.|->'),
 S('int offset=${n}; java.util.function.IntSupplier f=~() -> offset~; System.out.println(f.getAsInt());','${n}','0|Compile error','offset is effectively final and can be captured.','offset|() -> 0'),
 S('var a=new java.util.ArrayList<String>(); Runnable f=() -> a.~add~("${word}"); f.run(); System.out.println(a.size());','1','0|Compile error','Capturing a stable reference does not freeze the referenced list.','remove|contains')),
 L('streams','Lazy streams and terminal operations','Streams describe processing pipelines, not reusable containers. Intermediate operations are lazy; a terminal operation consumes the stream. map transforms, filter retains matching elements, and toList produces an unmodifiable result. Avoid depending on side effects in stream stages.',
 S('System.out.println(java.util.stream.Stream.of("${word}").~map~(String::length).findFirst().orElse(0));','${length}','0|Compile error','map converts each String to its length before the terminal search.','filter|peek'),
 S('System.out.println(java.util.stream.IntStream.of(${n},0).~filter~(x -> x>0).count());','1','2|0','Only the positive element survives the predicate.','map|limit'),
 S('System.out.println(java.util.stream.IntStream.of(${n},${m}).~sum()~);','${add}','${mul}|2','sum is a terminal reduction over the integer stream.','count()|findFirst()'),
 S('var result=java.util.stream.Stream.of("${word}").~toList()~; System.out.println(result.get(0));','${word}','Compile error|null','toList materializes a list from the pipeline.','iterator()|count()')),
 L('optional','Absence and Optional contracts','Optional makes possible absence explicit in a return value. map transforms a present value; flatMap avoids nested optionals. orElseGet computes a fallback lazily, unlike an eagerly evaluated argument to orElse. Avoid get without proving presence.',
 S('System.out.println(java.util.Optional.<String>empty().~orElse~("${word}"));','${word}','null|Compile error','An empty optional selects the supplied fallback.','get|of'),
 S('System.out.println(java.util.Optional.of("${word}").~map~(String::length).orElse(0));','${length}','0|Compile error','map applies the function to the present value.','filter|ifPresent'),
 S('System.out.println(java.util.Optional.empty().~isPresent()~);','false','true|null','isPresent distinguishes a value from absence.','isEmpty()|get()'),
 S('var value=java.util.Optional.<String>empty(); System.out.println(value.~orElseGet~(() -> "${word}"));','${word}','null|Compile error','orElseGet invokes the supplier only when the optional is empty.','orElse|map')),
 L('packages','Packages, visibility, and annotations','Package declarations qualify type names. Imports shorten names but do not install dependencies. Public APIs should expose deliberate contracts; package-private members support local implementation. Annotations are metadata interpreted by a compiler, tool, or runtime mechanism.',
 S('// Beginning of src/app/Main.java:\n~package~ app;','Declares the package app','Downloads app|Makes all fields public','The package declaration contributes to the fully qualified class name.','import|module','What does this declaration do?'),
 S('~import~ java.util.List;','Allows the simple name List for this type','Loads every dependency from the internet|Copies List source into this file','An import only affects name resolution.','package|requires','What does this declaration do?'),
 S('class Base {int size(){return 1;}}\nclass Child extends Base {~@Override~ int size(){return ${n};}}','Compiler checks that size overrides a supertype method','Method becomes static|Method is run at startup','Override catches accidental signature mismatches.','@Deprecated|@SuppressWarnings("unused")','What check does this annotation request?'),
 S('// In module-info.java:\nmodule app {~requires~ java.sql;}','Declares readability of the java.sql module','Publishes the app package|Opens all fields to reflection','requires declares a module dependency, distinct from imports and exports.','exports|opens','What relationship is declared?')),
 L('testing','Assertions and testable boundaries','Separate pure behavior from console and file boundaries so it can be checked independently. Java assertions are disabled unless enabled, so do not use assert for required input validation. Objects.requireNonNull enforces a runtime precondition. Unit-test frameworks are intentionally outside this core track.',
 S('$ java ~-ea~ Main','Enables Java assertions','Runs every JUnit test|Disables exceptions','-ea enables assertion evaluation for this run.','-da|--version','What does the option do?'),
 S('int actual=${n}+1; if(actual != ${next}) ~throw new AssertionError()~; System.out.println("ok");','ok','Throws AssertionError|Compile error','An explicit conditional check works regardless of assertion flags.','return|System.out.println("bad")'),
 S('try {java.util.Objects.~requireNonNull~(null,"${word}");} catch(NullPointerException e){System.out.println(e.getMessage());}','${word}','null|No output','requireNonNull fails immediately with the supplied diagnostic.','isNull|nonNull'),
 S('System.out.println(java.util.Objects.~equals~("${word}",null));','false','true|Throws NullPointerException','Objects.equals handles a null operand without dereferencing it.','requireNonNullElse|compare')),
 L('threads','Threads, joining, and visibility','Starting a thread schedules work; it does not guarantee completion before the next line. join waits and establishes visibility of completed writes. Java 21 virtual threads are lightweight threads for blocking workloads, not a promise of faster CPU computation. Synchronization protects shared invariants.',
 S('Thread t=new Thread(() -> System.out.println("${word}")); t.~start()~; t.join();','${word}','No output|Compile error','start launches the worker and join waits for it.','interrupt()|setDaemon(true)'),
 S('int[] result={0}; Thread t=new Thread(() -> result[0]=${n}); t.start(); t.~join()~; System.out.println(result[0]);','${n}','Always 0|Compile error','After a successful join, the worker write is visible to this thread.','isAlive()|getName()'),
 S('var t=Thread.~ofVirtual()~.start(() -> System.out.println("${word}")); t.join();','${word}','Compile error|No output','The builder starts a virtual thread; join still waits for completion.','currentThread()|interrupted()'),
 S('var n=new java.util.concurrent.atomic.AtomicInteger(${n}); System.out.println(n.~incrementAndGet()~);','${next}','${n}|0','The atomic operation increments and returns the new value.','getAndIncrement()|get()')),
 L('futures','Completion stages and asynchronous failures','CompletableFuture represents a result that may arrive later. thenApply transforms success, thenCompose chains another future, and exceptionally recovers from failure. join waits and wraps failures in CompletionException. Avoid blocking arbitrary executor threads without understanding the execution model.',
 S('var f=java.util.concurrent.CompletableFuture.completedFuture(${n}); System.out.println(f.~thenApply~(x -> x+1).join());','${next}','${n}|Compile error','thenApply transforms the completed value.','thenAccept|thenRun'),
 S('var f=java.util.concurrent.CompletableFuture.completedFuture("${word}"); System.out.println(f.~join()~);','${word}','null|Compile error','join obtains the result, waiting if necessary.','isDone()|toString()'),
 S('var f=java.util.concurrent.CompletableFuture.<Integer>failedFuture(new Exception()); System.out.println(f.~exceptionally~(e -> ${n}).join());','${n}','Throws CompletionException|Compile error','exceptionally substitutes a value for an exceptional completion.','thenApply|thenAccept'),
 S('var f=java.util.concurrent.CompletableFuture.completedFuture(${n}); System.out.println(f.~thenCompose~(x -> java.util.concurrent.CompletableFuture.completedFuture(x+1)).join());','${next}','A nested future|Compile error','thenCompose flattens the future returned by the callback.','thenApply|thenAccept')),
 ]

 # Teach repair immediately after identifying a final-binding error.
 result[1]['scenarios'][3]['completion'] = S(
  'int count=${n}; ~count++~; System.out.println(count);', '${next}', '${n}|0',
  'Use a mutable local int and increment it once.', 'count--|count=0')
 return result
